    let mut inner = self.inner.lock();
    let ret = inner.requested_thread_count == 0
        && inner.ready_threads.is_empty()
        && inner.started_thread_count < inner.max_threads;
    if ret {
        inner.requested_thread_count += 1
    }
    ret
